  1	\chapter{The Pauli basis test}
  2	\label{chap:qpbt-test}
  3	% Paper label sec:pauli-verifier kept for cross-reference fidelity; it resolves to this chapter.
  4	\label{sec:pauli-verifier}
  5	
  6	This chapter defines the two testing primitives underlying the question-reduction step: the \emph{classical low individual degree game}, in its simultaneous form, and the \emph{Pauli basis test}, a nonlocal game built from the classical game together with the Magic Square game. We state the quantum soundness of the classical game (Theorem~\ref{lem:ld-soundness}, imported, with the facts required by the identification, which remain to be proved, recorded in \cite{gap:qpbt_ld-dimension-divisibility}; see Remark~\ref{rem:ld-soundness-provider}), the rigidity of the Magic Square game (Theorem~\ref{thm:ms-rigidity}, imported), completeness of the Pauli basis test (Lemma~\ref{lem:pauli-completeness}), and the main soundness theorem for the Pauli basis test (Theorem~\ref{thm:pauli}), whose proof occupies Chapters~\ref{chap:qpbt-observables}--\ref{chap:qpbt-extraction} and is completed in Chapter~\ref{chap:qpbt-extraction} only modulo the proof obligation documented in \cite{gap:qpbt_ld-dimension-divisibility}. The chapter closes with the qubit form of the soundness statement (Corollary~\ref{cor:pauli-binary}) and the canonical parameter choice with its soundness bound (Definition~\ref{def:introparams}, Lemma~\ref{lem:delta-bound}).
  7	
  8	Throughout, the two players are denoted $\mathrm A$ and $\mathrm B$; for $w \in \{\mathrm A,\mathrm B\}$ we write $\overline w$ for the other player. Games, strategies, values, conditionally linear (CL) functions and distributions, typed distributions sampled from the edges of a graph, and the state-dependent approximation $\approx_\delta$ between families of measurement operators are as in Chapter~\ref{chap:qpbt-games}; the algebraic material on lines, canonical linear maps, the low-degree encoding, and generalized Pauli observables is from Chapter~\ref{chap:qpbt-algebra}.
  9	
 10	\section{The classical low individual degree game}
 11	% Paper labels sec:ld-verifier and sec:ld-game kept for cross-reference fidelity.
 12	\label{sec:ld-verifier}
 13	\label{sec:ld-game}
 14	
 15	The classical low individual degree game is a two-player game based on the low individual degree variant of the multilinearity test of Babai, Fortnow, and Lund. In the basic version, one player (the ``points player'') receives a uniformly random point $u \in \F_q^m$ and answers with a value $a \in \F_q$, while the other player (the ``lines player'') receives a random line through $u$ --- either axis-parallel or diagonal --- and answers with a univariate polynomial describing the restriction of a global function to that line. If the players share a polynomial $g\colon \F_q^m \to \F_q$ of individual degree at most $d$ and answer with $g(u)$ and with the restriction $g|_\ell$, they win with probability $1$; the soundness theorem below states that the converse approximately holds. In the simultaneous version, the players' answers are $k$-tuples, checked coordinatewise against a $k$-tuple of low individual degree polynomials.
 16	
 17	\begin{definition}[The classical low individual degree game: parameters and registers]\label{def:ld-game}
 18		\uses{def:game, def:admissible-size}
 19		% The source fixes \N to be the set of positive integers
 20		% (references/qpbt-paper/04_preliminaries.tex:6) and takes m, d, ldc in \N
 21		% (references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:33-35),
 22		% so the positivity below is the source's implicit domain, stated explicitly.
 23		% It is load-bearing: at d = 0 or k = 0 the prefactor a(dmk)^a of delta_ld in
 24		% lem:ld-soundness vanishes, and at d = 0 the resulting exact conclusions fail
 25		% (e.g. at (q,m,d,k) = (2,1,0,1) with eps = 1). The case k = 0, though it would
 26		% hold trivially, is likewise outside the source's domain and is omitted.
 27		The game $\mathfrak{G}^{\mathrm{ld}}$ is parametrized by a tuple $\mathsf{ldparams} = (q,m,d,k)$, where $m, d, k \ge 1$ are integers, $q \in \N$ is an admissible field size (Definition~\ref{def:admissible-size}), and $m$ divides $q$. We write $\mathfrak{G}^{\mathrm{ld}}_{\mathsf{ldparams}}$ to emphasize the dependence on the parameter tuple. The type set of $\mathfrak{G}^{\mathrm{ld}}$ is
 28		\[
 29			\mathcal T^{\mathrm{ld}} = \{\mathsf{Point}, \mathsf{ALine}, \mathsf{DLine}\}\;,
 30		\]
 31		and the distribution over type pairs $(t_{\mathrm A}, t_{\mathrm B})$ is uniform over $\mathcal T^{\mathrm{ld}} \times \mathcal T^{\mathrm{ld}}$. The ambient space is the direct sum $V = V_X \oplus V_I \oplus V_V$ of three register subspaces: the \emph{point register} $V_X \cong \F_q^m$, the \emph{coordinate register} $V_I \cong \F_q$, and the \emph{direction register} $V_V \cong \F_q^m$. Elements of $V$ are identified with triples $(u,s,v) \in \F_q^m \times \F_q \times \F_q^m$. The question distribution and the win predicate of $\mathfrak{G}^{\mathrm{ld}}$ are specified in Definitions~\ref{def:ld-question-distribution} and~\ref{def:ld-win-predicate} below.
 32	\end{definition}
 33	
 34	\begin{definition}[Question distribution of the classical low individual degree game]\label{def:ld-question-distribution}
 35		\uses{def:ld-game, def:cl-func, def:cl-dist, lem:cl-concat, def:cl-canonical, def:line-representative}
 36		Let $\mathsf{ldparams} = (q,m,d,k)$ be as in Definition~\ref{def:ld-game}. Define $L_{\mathsf{Point}}$ to be the $1$-level CL function on $V$ that projects onto $V_X$: for every $(u,s,v) \in V$,
 37		\begin{equation}
 38			\label{eq:cl-ptf}
 39			L_{\mathsf{Point}}(u,s,v) = (u,0,0)\;.
 40		\end{equation}
 41		For $s \in \F_q$, let $\chi(s)$ be the unique integer such that
 42		\begin{equation}
 43			\label{eq:chi-func}
 44			s = (\chi(s)-1)\,\frac{q}{m} + r
 45		\end{equation}
 46		for some $0 \le r < q/m$, where $s$ is interpreted as an integer in $\{0,1,\ldots,q-1\}$ under the identification of $\F_q$ with binary strings fixed in Chapter~\ref{chap:qpbt-algebra}. Since $m$ divides $q$, when $s$ is uniformly distributed on $\F_q$ the index $\chi(s)$ is uniformly distributed on $\{1,2,\ldots,m\}$. Define $L_{\mathsf{ALine}}$ by
 47		\begin{equation}
 48			\label{eq:cl-alnf}
 49			L_{\mathsf{ALine}}(u,s,v) = \bigl(L^{\mathrm{Ln}}_{e_i}(u),\, s,\, 0\bigr)\quad\text{for all } (u,s,v) \in V\;,
 50		\end{equation}
 51		where $i = \chi(s)$ and $L^{\mathrm{Ln}}_v$ denotes the canonical linear map with one-dimensional kernel spanned by $v$, used to compute canonical representatives of lines (Definition~\ref{def:line-representative}). The function $L_{\mathsf{ALine}}$ is the concatenation (in the sense of Lemma~\ref{lem:cl-concat}) of the $1$-level CL function projecting $V_I \oplus V_V$ onto $V_I$ with the family of $1$-level CL functions $\{L^{\mathrm{Ln}}_{e_i}\}$ on $V_X$ indexed by $i \in \{1,\ldots,m\}$; thus $L_{\mathsf{ALine}}$ is a $2$-level CL function. Define $L_{\mathsf{DLine}}$ by
 52		\begin{equation}
 53			\label{eq:cl-dlnf}
 54			L_{\mathsf{DLine}}(u,s,v) = \bigl(L^{\mathrm{Ln}}_{\pi_{i-1}(v)}(u),\, s,\, \pi_{i-1}(v)\bigr)\;,
 55		\end{equation}
 56		where $i = \chi(s)$ and $\pi_{i-1}$ zeroes out the first $i-1$ coordinates of its input. The function $L_{\mathsf{DLine}}$ is the concatenation of (i) the identity on $V_I$, (ii) for each $i$ the $1$-level CL function $v \mapsto \pi_{i-1}(v)$ on $V_V$, and (iii) for each pair $(s,v') \in V_I \oplus V_V$ the $1$-level CL function $L^{\mathrm{Ln}}_{v'}$ on $V_X$; thus $L_{\mathsf{DLine}}$ is a $3$-level CL function.
 57	
 58		The question distribution of $\mathfrak{G}^{\mathrm{ld}}$ is the typed CL distribution obtained as follows: sample a type pair $(t_{\mathrm A}, t_{\mathrm B})$ uniformly from $\mathcal T^{\mathrm{ld}} \times \mathcal T^{\mathrm{ld}}$, sample $z = (u,s,v)$ uniformly from $V$, and send each player $w \in \{\mathrm A,\mathrm B\}$ the question $(t_w, L_{t_w}(z))$.
 59	\end{definition}
 60	
 61	The next two lemmas show that the CL functions $L_{\mathsf{Point}}$, $L_{\mathsf{ALine}}$, $L_{\mathsf{DLine}}$ give rise to the axis-parallel and diagonal line-versus-point distributions.
 62	Their formal coordinate labels are $r\in\{0,\ldots,m-1\}$, with label $r$
 63	representing the paper's coordinate $r+1$.
 64	
 65	\begin{lemma}\label{lem:alnf}
 66		\lean{MIPStarRE.QPBT.aLinePointDist_point_marginal_uniform, MIPStarRE.QPBT.aLinePointDist_mem_line}
 67		\leanok
 68		\uses{def:ld-question-distribution, def:line}
 69		Consider the pair $(\ell, u)$ sampled in the following way: first, sample the tuple $\bigl((u_0,s,0),(u,0,0)\bigr)$ from the CL distribution $\mu_{L_{\mathsf{ALine}}, L_{\mathsf{Point}}}$, and let $\ell = \ell(u_0, e_i)$ where $i = \chi(s)$. Then $u$ is a uniformly random point in $\F_q^m$, and $\ell$ is a line that goes through $u$ and is parallel to a uniformly random axis $i \in \{1,2,\ldots,m\}$.
 70	\end{lemma}
 71	\begin{proof}
 72		\uses{def:line-representative}
 73		Since $s$ is uniformly random in $\F_q$ and $m$ divides $q$, the index $i = \chi(s)$ is uniformly random in $\{1,2,\ldots,m\}$, so $(u_0,s)$ specifies a uniformly random axis-parallel line $\ell(u_0,e_i)$. Since $u_0 = L^{\mathrm{Ln}}_{e_i}(u)$ is the canonical representative of the line through $u$ in direction $e_i$, we have $u \in \ell(u_0,e_i)$.
 74	\end{proof}
 75	
 76	\begin{lemma}\label{lem:dlnf}
 77		\lean{MIPStarRE.QPBT.dLinePointDist_point_marginal_uniform, MIPStarRE.QPBT.dLinePointDist_mem_line, MIPStarRE.QPBT.dLinePointDist_prefix_zero}
 78		\leanok
 79		\uses{def:ld-question-distribution, def:line}
 80		Consider the pair $(\ell, u)$ sampled in the following way: first, sample the tuple $\bigl((u_0,s,v),(u,0,0)\bigr)$ from the CL distribution $\mu_{L_{\mathsf{DLine}}, L_{\mathsf{Point}}}$, and let $\ell = \ell(u_0, v)$ where $i = \chi(s)$. Then $u$ is a uniformly random point in $\F_q^m$, and $\ell$ is a random diagonal line that goes through $u$ and shares its first $i-1$ coordinates with $u$, for uniformly random $i \in \{1,2,\ldots,m\}$.
 81	\end{lemma}
 82	\begin{proof}
 83		\uses{lem:alnf}
 84		The proof is identical to that of Lemma~\ref{lem:alnf}: uniformity of $s$ makes $i = \chi(s)$ uniform, the direction component of the sampled tuple is $\pi_{i-1}(v)$ for uniform $v$ (so its first $i-1$ coordinates vanish), and $u_0 = L^{\mathrm{Ln}}_{\pi_{i-1}(v)}(u)$ places $u$ on the line $\ell(u_0,\pi_{i-1}(v))$.
 85	\end{proof}
 86	
 87	\begin{definition}[Line-point distributions]\label{def:line-point-dist}
 88		\lean{MIPStarRE.QPBT.LineKind, MIPStarRE.QPBT.LineDesc}
 89		\lean{MIPStarRE.QPBT.aLinePointDist, MIPStarRE.QPBT.dLinePointDist}
 90		\lean{MIPStarRE.QPBT.linePointDist}
 91		\lean{MIPStarRE.QPBT.aLinePointDist_isProbability}
 92		\lean{MIPStarRE.QPBT.dLinePointDist_isProbability}
 93		\lean{MIPStarRE.QPBT.linePointDist_isProbability}
 94		\leanok
 95		\uses{def:ld-question-distribution, lem:alnf, lem:dlnf}
 96		The \emph{axis line-point distribution} $D_{\mathsf{ALine}}$ is the distribution $\mu_{L_{\mathsf{ALine}}, L_{\mathsf{Point}}}$ over pairs $(\ell = (u_0,e_i),\, u)$, where we omit the $0$ components for simplicity. The \emph{diagonal line-point distribution} $D_{\mathsf{DLine}}$ is the distribution $\mu_{L_{\mathsf{DLine}}, L_{\mathsf{Point}}}$ over pairs $(\ell = (u_0,s,v),\, u)$. The \emph{line-point distribution} $D_{\mathsf{Line}}$ is the equal mixture of the two: with probability $\tfrac12$ output a sample from $D_{\mathsf{ALine}}$, and with probability $\tfrac12$ output a sample from $D_{\mathsf{DLine}}$.
 97	\end{definition}
 98	
 99	\begin{definition}[Win predicate of the classical low individual degree game]\label{def:ld-win-predicate}
100		\uses{def:ld-game, def:ld-question-distribution, def:line, def:polyfunc}
101		Fix $\mathsf{ldparams} = (q,m,d,k)$. Answers in the game $\mathfrak{G}^{\mathrm{ld}}_{\mathsf{ldparams}}$ take the following forms, depending on the question type; answers not of the prescribed form are rejected.
102		\begin{itemize}
103			\item Type $\mathsf{Point}$, question content $u \in \F_q^m$: the answer is an element of $\F_q^k$.
104			\item Type $\mathsf{ALine}$, question content $(u_0,s) \in \F_q^m \times \F_q$, specifying the axis-parallel line $\ell(u_0,e_i)$ with $i = \chi(s)$: the answer is a $k$-tuple $(f_1,\ldots,f_k)$ of univariate polynomials $f_j\colon \F_q \to \F_q$ of degree at most $d$, each given by its $d+1$ coefficients.
105			\item Type $\mathsf{DLine}$, question content $(u_0,s,v) \in \F_q^m \times \F_q \times \F_q^m$, specifying the diagonal line $\ell(u_0,v')$ with $v' = \pi_{i-1}(v)$ and $i = \chi(s)$: the answer is a $k$-tuple of univariate polynomials of degree at most $md$.
106		\end{itemize}
107		The win predicate $D^{\mathrm{ld}} = D^{\mathrm{ld}}_{\mathsf{ldparams}}$ is the function of the tuple $(t_{\mathrm A}, x_{\mathrm A}, t_{\mathrm B}, x_{\mathrm B}, a_{\mathrm A}, a_{\mathrm B})$ determined by the following clauses, evaluated for $w \in \{\mathrm A,\mathrm B\}$; in all cases where no action is indicated, the predicate accepts.
108		\begin{enumerate}
109			\item (\textbf{Consistency test}) If $t_{\mathrm A} = t_{\mathrm B}$, accept if and only if $a_{\mathrm A} = a_{\mathrm B}$.
110			% The source phrases both clauses with "the" t such that x = u_0 + tv; that phrase
111			% does not determine t on diagonal questions with direction v' = 0, which the
112			% question distribution samples with positive probability. The universal
113			% quantification over t used here is the local correction; see the remark below.
114			\item (\textbf{Axis-parallel line-versus-point test}) If $t_w = \mathsf{ALine}$ and $t_{\overline w} = \mathsf{Point}$, accept if and only if $f_j(t) = (a_{\overline w})_j$ for all $j \in \{1,2,\ldots,k\}$ and all $t \in \F_q$ such that $x_{\overline w} = u_0 + t e_i$, where $i = \chi(s)$.
115			\item (\textbf{Diagonal line-versus-point test}) If $t_w = \mathsf{DLine}$ and $t_{\overline w} = \mathsf{Point}$, accept if and only if $f_j(t) = (a_{\overline w})_j$ for all $j \in \{1,2,\ldots,k\}$ and all $t \in \F_q$ such that $x_{\overline w} = u_0 + t v'$, where $v' = \pi_{i-1}(v)$ and $i = \chi(s)$.
116		\end{enumerate}
117		The game $\mathfrak{G}^{\mathrm{ld}}_{\mathsf{ldparams}}$ is the typed game with type set $\mathcal T^{\mathrm{ld}}$, the question distribution of Definition~\ref{def:ld-question-distribution}, and win predicate $D^{\mathrm{ld}}_{\mathsf{ldparams}}$.
118	\end{definition}
119	
120	\begin{remark}[Diagonal questions with zero direction]\label{rem:ld-win-zero-direction}
121		The source states the two line-versus-point clauses with ``the'' $t \in \F_q$ such that $x_{\overline w} = u_0 + t v$. When the direction is nonzero and $x_{\overline w}$ lies on the line, exactly one such $t$ exists and the formulation above agrees with the source. But zero directions occur: Definition~\ref{def:line} explicitly permits them, and the question distribution of Definition~\ref{def:ld-question-distribution} produces $\mathsf{DLine}$ questions with $v' = \pi_{i-1}(v) = 0$ with positive probability, namely whenever the last $m - i + 1$ coordinates of $v$ vanish. In that case $\ell(u_0, 0) = \{u_0\}$, every $t \in \F_q$ satisfies $x_{\overline w} = u_0 + t v'$ when $x_{\overline w} = u_0$, and the source clause does not determine acceptance for a nonconstant answer polynomial. The universal quantification over $t$ adopted in Definition~\ref{def:ld-win-predicate} makes the predicate a well-defined function of its arguments; it accepts vacuously when no such $t$ exists, a case the question distribution never produces. Completeness is unaffected: the restriction of a polynomial $g$ to the singleton line $\ell(u_0,0)$, expressed through the parameterization $t \mapsto u_0 + t \cdot 0$, is the constant polynomial with value $g(u_0)$, which passes the check for every $t$. Soundness is likewise unaffected: zero directions occur with probability at most $2/(mq)$, so any acceptance convention on this event changes success probabilities by at most that amount; the game-correspondence obligation enumerated in the proof of Theorem~\ref{lem:ld-soundness} accounts for this event explicitly, and an error of this shape is absorbed into the universal constants of $\delta_{\mathrm{ld}}$.
122	\end{remark}
123	
124	The soundness properties of the low individual degree game are expressed in terms of the following class of measurements.
125	
126	\begin{definition}[Low-degree polynomial measurements]\label{def:ld-meas}
127		\lean{MIPStarRE.QPBT.PolyIndex, MIPStarRE.QPBT.PolyMeas, MIPStarRE.QPBT.PolyMeasFamily, MIPStarRE.QPBT.PolyMeasTuple}
128		\leanok
129		\uses{def:polyfunc, def:polymeasurements, def:polynomials-degree}
130		Let $\polymeas{m}{q}{d}$ denote the set of POVM measurements indexed by $\polyfunc{m}{q}{d}$, the polynomial representatives of individual degree at most $d$ in each variable; this is the notion of Definition~\ref{def:polymeasurements}, and the argument order $(m,q,d)$ follows that definition (the paper orders the arguments as $(m,d,q)$). By Definition~\ref{def:polynomials-degree}, evaluation identifies these representatives with the corresponding polynomial functions $g\colon \F_q^m \to \F_q$, bijectively whenever $d \le q-1$; at the canonical parameters (Definition~\ref{def:introparams}, where $d = 1 \le q-1$) the identification is bijective; the general statements of this chapter quantify over all admissible tuples and are read through the representative convention. More generally, for an integer $k$ and tuples $m = (m_1,\ldots,m_k)$, $q = (q_1,\ldots,q_k)$, $d = (d_1,\ldots,d_k)$, let $\mathrm{PolyMeas}(m,q,d,k)$ denote the set of measurements $G = \{G_{g_1,\ldots,g_k}\}$ such that for each $i \in \{1,\ldots,k\}$, the outcome index $g_i$ is a polynomial $g_i\colon \F_{q_i}^{m_i} \to \F_{q_i}$ of individual degree at most $d_i$.
131		The formal tuple components are labelled by $r\in\{0,\ldots,k-1\}$, with
132		label $r$ representing the paper's component $r+1$.
133	\end{definition}
