413	\begin{theorem}[Soundness of the Pauli basis test]\label{thm:pauli}
414		\uses{def:pauli-question-distribution, def:pauli-win-predicate, def:admissible, def:tensor-product-value, def:EPR, lem:pauli-observable-expansion, def:povm-distance}
415		There exists a function
416		\[
417			\delta_{\mathrm{qld}}(\eps, m, d, q) = a\,(md)^a \bigl( \eps^b + q^{-b} + 2^{-bmd} \bigr)
418		\]
419		for universal constants $a \ge 1$ and $0 < b < 1$ such that the following holds. For all admissible parameter tuples $\mathsf{qldparams} = (q,m,d)$ and for all strategies $\mathcal S = (\ket\psi, A, B)$ for the game $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ that succeed with probability at least $1 - \eps$, there exist local isometries $\phi_{\mathrm A}\colon \hilb_{\mathrm A} \to \hilb_{\mathrm A'} \ot \hilb_{\mathrm A''}$ and $\phi_{\mathrm B}\colon \hilb_{\mathrm B} \to \hilb_{\mathrm B'} \ot \hilb_{\mathrm B''}$, where $\ket\psi \in \hilb_{\mathrm A} \ot \hilb_{\mathrm B}$ and $\hilb_{\mathrm A''}, \hilb_{\mathrm B''} \cong (\C^q)^{\ot M}$ with $M = 2^m$, and a state $\ket{\mathrm{aux}} \in \hilb_{\mathrm A'} \ot \hilb_{\mathrm B'}$, such that:
420		\begin{enumerate}
421			\item $\bigl\| \phi_{\mathrm A} \ot \phi_{\mathrm B} \ket\psi - \ket{\mathrm{aux}} \ot \ket{\mathrm{EPR}_q}^{\ot M} \bigr\| \le \delta_{\mathrm{qld}}(\eps, m, d, q)$;
422			% The paper here has the typo "phi_alice \ot phi_B"; both maps are the isometries above.
423			\item letting $\tilde A^x_a = \phi_{\mathrm A} A^x_a \phi_{\mathrm A}^\dagger$ and $\tilde B^y_b = \phi_{\mathrm B} B^y_b \phi_{\mathrm B}^\dagger$, for $W \in \{X, Z\}$,
424			\begin{align*}
425				\tilde A^{(\mathsf{Pauli},W)}_u \ot I_{\mathrm{B'B''}} &\approx_{\delta_{\mathrm{qld}}} (\tau^W_u)_{\mathrm A''} \ot I_{\mathrm{A'B'B''}}\;,\\
426				I_{\mathrm{A'A''}} \ot \tilde B^{(\mathsf{Pauli},W)}_u &\approx_{\delta_{\mathrm{qld}}} I_{\mathrm{A'A''B'}} \ot (\tau^W_u)_{\mathrm B''}\;,
427			\end{align*}
428			where the $\approx_{\delta_{\mathrm{qld}}}$ statements hold with respect to the state $\ket{\mathrm{aux}}_{\mathrm{A'B'}} \ot \ket{\mathrm{EPR}_q}^{\ot M}_{\mathrm{A''B''}}$ and the answer summation is over $u \in \F_q^M$.
429		\end{enumerate}
