411	We now state the main soundness property of the Pauli basis test; the statement is an adaptation of the self-testing theorem of~\cite{Natarajan2018NEEXP} (Theorem~6.4 there). Unlike Theorem~\ref{lem:ld-soundness}, no projectivity assumption is made on the strategy.
412	
413	\begin{theorem}[Soundness of the Pauli basis test]\label{thm:pauli}
414		\uses{def:pauli-question-distribution, def:pauli-win-predicate, def:admissible, def:tensor-product-value, def:EPR, lem:pauli-observable-expansion, def:povm-distance}
415		There exists a function
416		\[
417			\delta_{\mathrm{qld}}(\eps, m, d, q) = a\,(md)^a \bigl( \eps^b + q^{-b} + 2^{-bmd} \bigr)
418		\]
419		for universal constants $a \ge 1$ and $0 < b < 1$ such that the following holds. For all admissible parameter tuples $\mathsf{qldparams} = (q,m,d)$ and for all strategies $\mathcal S = (\ket\psi, A, B)$ for the game $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ that succeed with probability at least $1 - \eps$, there exist local isometries $\phi_{\mathrm A}\colon \hilb_{\mathrm A} \to \hilb_{\mathrm A'} \ot \hilb_{\mathrm A''}$ and $\phi_{\mathrm B}\colon \hilb_{\mathrm B} \to \hilb_{\mathrm B'} \ot \hilb_{\mathrm B''}$, where $\ket\psi \in \hilb_{\mathrm A} \ot \hilb_{\mathrm B}$ and $\hilb_{\mathrm A''}, \hilb_{\mathrm B''} \cong (\C^q)^{\ot M}$ with $M = 2^m$, and a state $\ket{\mathrm{aux}} \in \hilb_{\mathrm A'} \ot \hilb_{\mathrm B'}$, such that:
420		\begin{enumerate}
421			\item $\bigl\| \phi_{\mathrm A} \ot \phi_{\mathrm B} \ket\psi - \ket{\mathrm{aux}} \ot \ket{\mathrm{EPR}_q}^{\ot M} \bigr\| \le \delta_{\mathrm{qld}}(\eps, m, d, q)$;
422			% The paper here has the typo "phi_alice \ot phi_B"; both maps are the isometries above.
423			\item letting $\tilde A^x_a = \phi_{\mathrm A} A^x_a \phi_{\mathrm A}^\dagger$ and $\tilde B^y_b = \phi_{\mathrm B} B^y_b \phi_{\mathrm B}^\dagger$, for $W \in \{X, Z\}$,
424			\begin{align*}
425				\tilde A^{(\mathsf{Pauli},W)}_u \ot I_{\mathrm{B'B''}} &\approx_{\delta_{\mathrm{qld}}} (\tau^W_u)_{\mathrm A''} \ot I_{\mathrm{A'B'B''}}\;,\\
426				I_{\mathrm{A'A''}} \ot \tilde B^{(\mathsf{Pauli},W)}_u &\approx_{\delta_{\mathrm{qld}}} I_{\mathrm{A'A''B'}} \ot (\tau^W_u)_{\mathrm B''}\;,
427			\end{align*}
428			where the $\approx_{\delta_{\mathrm{qld}}}$ statements hold with respect to the state $\ket{\mathrm{aux}}_{\mathrm{A'B'}} \ot \ket{\mathrm{EPR}_q}^{\ot M}_{\mathrm{A''B''}}$ and the answer summation is over $u \in \F_q^M$.
429		\end{enumerate}
430	\end{theorem}
431	
432	The proof of Theorem~\ref{thm:pauli} is the adaptation, to low individual degree, of the analysis of the quantum low-degree test of Natarajan and Vidick; it is developed in Chapters~\ref{chap:qpbt-observables} and~\ref{chap:qpbt-combining} and concluded in Chapter~\ref{chap:qpbt-extraction}, where the argument is complete only modulo the unresolved divisibility obligation documented in \cite{gap:qpbt_ld-dimension-divisibility}. It relies on the classical soundness theorem (Theorem~\ref{lem:ld-soundness}) and on the rigidity of the Magic Square game (Theorem~\ref{thm:ms-rigidity}).
433	
434	The strategies appearing in Lemma~\ref{lem:pauli-completeness} and in the conclusion of Theorem~\ref{thm:pauli} are phrased in terms of qudit Pauli measurements and maximally entangled states of $q$-dimensional qudits. For the intended application it is more convenient to work with qubits: since the field sizes $q$ used here are powers of $2$, the conclusions can be restated in terms of qubit EPR pairs and qubit Pauli measurements.
435	
436	\begin{corollary}[Qubit form of the soundness of the Pauli basis test]\label{cor:pauli-binary}
437		\lean{MIPStarRE.QPBT.pauli_soundness_qubit}
438		\leanok
439		\uses{def:pauli-question-distribution, def:pauli-win-predicate, def:admissible, def:tensor-product-value, def:EPR, def:povm-distance, def:binary-representation}
440		There exists a function
441		\[
442			\delta_{\mathrm{qld}}(\eps, m, d, q) = a\,(md)^a \bigl( \eps^b + q^{-b} + 2^{-bmd} \bigr)
443		\]
444		% The paper's displayed function here writes the argument order (eps, q, m, d); the
445		% formula is the same, and its own item 1 reverts to (eps, m, d, q). See the remark below.
446		for universal constants $a \ge 1$ and $0 < b < 1$ such that the following holds. For all admissible parameter tuples $\mathsf{qldparams} = (q,m,d)$ and for all strategies $\mathcal S = (\ket\psi, A, B)$ for the game $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ that succeed with probability at least $1 - \eps$, there exist local isometries $\phi_{\mathrm A}\colon \hilb_{\mathrm A} \to \hilb_{\mathrm A'} \ot \hilb_{\mathrm A''}$ and $\phi_{\mathrm B}\colon \hilb_{\mathrm B} \to \hilb_{\mathrm B'} \ot \hilb_{\mathrm B''}$, where $\ket\psi \in \hilb_{\mathrm A} \ot \hilb_{\mathrm B}$ and $\hilb_{\mathrm A''}, \hilb_{\mathrm B''} \cong (\C^2)^{\ot M \log q}$ with $M = 2^m$, and a state $\ket{\mathrm{aux}} \in \hilb_{\mathrm A'} \ot \hilb_{\mathrm B'}$, such that:
447		\begin{enumerate}
448			\item $\bigl\| \phi_{\mathrm A} \ot \phi_{\mathrm B} \ket\psi - \ket{\mathrm{aux}} \ot \ket{\mathrm{EPR}_2}^{\ot M \log q} \bigr\| \le \delta_{\mathrm{qld}}(\eps, m, d, q)$;
449			\item letting $\tilde A^x_a = \phi_{\mathrm A} A^x_a \phi_{\mathrm A}^\dagger$ and $\tilde B^y_b = \phi_{\mathrm B} B^y_b \phi_{\mathrm B}^\dagger$, for $W \in \{X, Z\}$,
450			\begin{align*}
451				\tilde A^{(\mathsf{Pauli},W)}_u \ot I_{\mathrm{B'B''}} &\approx_{\delta_{\mathrm{qld}}} (\sigma^W_u)_{\mathrm A''} \ot I_{\mathrm{A'B'B''}}\;,\\
452				I_{\mathrm{A'A''}} \ot \tilde B^{(\mathsf{Pauli},W)}_u &\approx_{\delta_{\mathrm{qld}}} I_{\mathrm{A'A''B'}} \ot (\sigma^W_u)_{\mathrm B''}\;,
453			\end{align*}
454			where the $\approx_{\delta_{\mathrm{qld}}}$ statements hold with respect to the state $\ket{\mathrm{aux}}_{\mathrm{A'B'}} \ot \ket{\mathrm{EPR}_2}^{\ot M \log q}_{\mathrm{A''B''}}$ and the answer summation is over $u \in \F_q^M$. Here $\sigma^W_u$ denotes the tensor product of single-qubit Pauli measurements
455			\[
456				\bigotimes_{i=1}^{M} \bigotimes_{j=1}^{\log q} \sigma^W_{u_{ij}}\;,
457			\]
458			where $\kappa(u_i) = (u_{ij})_{1 \le j \le \log q}$ under the bijection $\kappa\colon \F_q \to \F_2^{\log q}$ of Chapter~\ref{chap:qpbt-algebra}.
459		\end{enumerate}
460	\end{corollary}
461	\begin{proof}
462		\uses{thm:pauli, lem:pauli-binary}
463		By Lemma~\ref{lem:pauli-binary}, since $q$ is a power of $2$ there are local isometries that map $\ket{\mathrm{EPR}_q}^{\ot M}$ to $\ket{\mathrm{EPR}_2}^{\ot M \log q}$ and map the generalized Pauli measurements $\tau^W_u$ to the qubit tensor products $\bigotimes_{i=1}^M \bigotimes_{j=1}^{\log q} \sigma^W_{u_{ij}}$, where $\kappa(u_i) = (u_{i1},\ldots,u_{i \log q})$. Composing these isometries with those produced by Theorem~\ref{thm:pauli} gives the statement.
464	\end{proof}
